import time

from acme import RateLimitError  # import path not confirmed by the docs results; adjust to your install

DEFAULT_WAIT_SECONDS = 5

def call_with_retry(do_request, max_attempts=3):
    for attempt in range(1, max_attempts + 1):
        try:
            return do_request()
        except RateLimitError as err:
            if attempt == max_attempts:
                raise
            wait = getattr(err, 'retry_after_seconds', None)
            if wait is None:
                wait = DEFAULT_WAIT_SECONDS
            time.sleep(wait)

